  // Get the height of a node
  getHeight(node) {
    if (node === null) {
      return 0;
    }
    return node.height;
  }

  // Get the balance factor of a node
  getBalanceFactor(node) {
    if (node === null) {
      return 0;
    }
    return this.getHeight(node.left) - this.getHeight(node.right);
  }

  // Update the height of a node
  updateHeight(node) {
    if (node === null) {
      return;
    }
    node.height = Math.max(this.getHeight(node.left), this.getHeight(node.right)) + 1;
  }

  // Perform a right rotation on a node
  rotateRight(node) {
    const newRoot = node.left;
    const newRightSubtree = newRoot.right;

    // Perform rotation
    newRoot.right = node;
    node.left = newRightSubtree;

    // Update heights
    this.updateHeight(node);
    this.updateHeight(newRoot);

    return newRoot;
  }

  // Perform a left rotation on a node
  rotateLeft(node) {
    const newRoot = node.right;
    const newLeftSubtree = newRoot.left;

    // Perform rotation
    newRoot.left = node;
    node.right = newLeftSubtree;

    // Update heights
    this.updateHeight(node);
    this.updateHeight(newRoot);

    return newRoot;
  }

  // Insert a value into the BST
  insert(value) {
    this.root = this.insertNode(this.root, value);
  }

  // Helper function to insert a node recursively
  insertNode(node, value) {
    // Perform normal BST insertion
    if (node === null) {
      return new Node(value);
    }

    if (value < node.value) {
      node.left = this.insertNode(node.left, value);
    } else {
      node.right = this.insertNode(node.right, value);
    }

    // Update height of current node
    this.updateHeight(node);

    // Check balance factor and rotate if necessary
    const balanceFactor = this.getBalanceFactor(node);

    if (balanceFactor > 1) {
      // Left subtree is taller
      if (value < node.left.value) {
        // Left-left case
        return this.rotateRight(node);
      }
      // Left-right case
      node.left = this.rotateLeft(node.left);
      return this.rotateRight(node);
    }

    if (balanceFactor < -1) {
      // Right subtree is taller
      if (value > node.right.value) {
        // Right-right case
        return this.rotateLeft(node);
      }
      // Right-left case
      node.right = this.rotateRight(node.right);
      return this.rotateLeft(node);
    }

    return node;
  }

  // Remove a value from the BST
  remove(value) {
    this.root = this.removeNode(this.root, value);
  }

  // Helper function to remove a node recursively
  removeNode(node, value) {
    if (node === null) {
      return null;
    }

    // Perform normal BST removal
    if (value < node.value) {
      node.left = this.removeNode(node.left, value);
    } else if (value > node.value) {
      node.right = this.removeNode(node.right, value);
    } else {
      // Node to be removed is found
      if (node.left === null && node.right === null) {
        // Leaf node case
        node = null;
      } else if (node.left === null || node.right === null) {
        // One child case
        node = node.left || node.right;
      } else {
        // Two children case
        const minRight = this.findMinNode(node.right);
        node.value = minRight.value;
        node.right = this.removeNode(node.right, minRight.value);
      }
    }

    if (node === null) {
      return node;
    }

    // Update height of current node
    this.updateHeight(node);

    // Check balance factor and rotate if necessary
    const balanceFactor = this.getBalanceFactor(node);

    if (balanceFactor > 1) {
      // Left subtree is taller
      if (this.getBalanceFactor(node.left) >= 0) {
        // Left-left case
        return this.rotateRight(node);
      }
      // Left-right case
      node.left = this.rotateLeft(node.left);
      return this.rotateRight(node);
    }

    if (balanceFactor < -1) {
      // Right subtree is taller
      if (this.getBalanceFactor(node.right) <= 0) {
        // Right-right case
        return this.rotateLeft(node);
      }
      // Right-left case
      node.right = this.rotateRight(node.right);
      return this.rotateLeft(node);
    }

    return node;
  }

  // Find the node with the minimum value in the BST
  findMinNode(node) {
    if (node === null || node.left === null) {
      return node;
    }
    return this.findMinNode(node.left);
  }

  // Print the BST in inorder traversal
  inorderTraversal(node) {
    if (node !== null) {
      this.inorderTraversal(node.left);
      console.log(node.value);
      this.inorderTraversal(node.right);
    }
  }
}

