class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if not -1000 <= value <= 1000:
            return

        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(value, self.root)

    def _insert_recursive(self, value, node):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(value, node.left)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(value, node.right)

    def search(self, value):
        return self._search_recursive(value, self.root) if self.root else False

    def _search_recursive(self, value, node):
        if node is None:
            return False

        if value == node.value:
            return True
        elif value < node.value:
            return self._search_recursive(value, node.left)
        else:
            return self._search_recursive(value, node.right)

    def delete(self, value):
        if not -1000 <= value <= 1000:
            return

        self.root = self._delete_recursive(value, self.root)

    def _delete_recursive(self, value, node):
        if node is None:
            return node

        if value < node.value:
            node.left = self._delete_recursive(value, node.left)
        elif value > node.value:
            node.right = self._delete_recursive(value, node.right)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                successor = self._find_min(node.right)
                node.value = successor.value
                node.right = self._delete_recursive(successor.value, node.right)

        return node

