### Response:
Here is an implementation of a C++ program to find the lowest common ancestor (LCA) of two given nodes in a Binary Search Tree (BST):

```cpp
#include <iostream>
using namespace std;

// Definition for a binary tree node
struct Node {
    int data;
    Node* left;
    Node* right;
};

// Function to create a new BST node
Node* createNode(int data) {
    Node* newNode = new Node();
    if (!newNode) {
        cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a node into a BST
Node* insertNode(Node* root, int data) {
    if (root == NULL) {
        root = createNode(data);
        return root;
    }
    if (data < root->data)
        root->left = insertNode(root->left, data);
    else if (data > root->data)
        root->right = insertNode(root->right, data);
    return root;
}

// Function to find the LCA of two nodes in a BST
Node* findLCA(Node* root, int n1, int n2) {
    if (root == NULL)
        return NULL;
    if (root->data > n1 && root->data > n2)
        return findLCA(root->left, n1, n2);
    if (root->data < n1 && root->data < n2)
        return findLCA(root->right, n1, n2);
    return root;
}

// Function to check if a node exists in a BST
bool doesNodeExist(Node* root, int data) {
    if (root == NULL)
        return false;
    if (root->data == data)
        return true;
    if (data < root->data)
        return doesNodeExist(root->left, data);
    else
        return doesNodeExist(root->right, data);
}

// Main function
int main() {
    Node* root = NULL;
    root = insertNode(root, 20);
    root = insertNode(root, 8);
    root = insertNode(root, 22);
    root = insertNode(root, 4);
    root = insertNode(root, 12);
    root = insertNode(root, 10);
    root = insertNode(root, 14);

    int n1, n2;
    cout << "Enter two nodes to find their LCA: ";
    cin >> n1 >> n2;

    if (!doesNodeExist(root, n1) || !doesNodeExist(root, n2)) {
        cout << "One or both nodes not found in the BST\n";
    } else {
        Node* lca = findLCA(root, n1, n2);
        cout << "Lowest Common Ancestor: " << lca->data << endl;
    }

    return 0;
}
```

