#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int value) {
        data = value;
        left = nullptr;
        right = nullptr;
    }
};

class BinaryTree {
private:
    Node* root;

    Node* insertRecursive(Node* current, int value) {
        if (current == nullptr) {
            return new Node(value);
        }

        if (value < current->data) {
            current->left = insertRecursive(current->left, value);
        }
        else if (value > current->data) {
            current->right = insertRecursive(current->right, value);
        }

        return current;
    }

    Node* deleteRecursive(Node* current, int value) {
        if (current == nullptr) {
            return nullptr;
        }

        if (value == current->data) {
            if (current->left == nullptr && current->right == nullptr) {
                delete current;
                return nullptr;
            }
            else if (current->left == nullptr) {
                Node* temp = current->right;
                delete current;
                return temp;
            }
            else if (current->right == nullptr) {
                Node* temp = current->left;
                delete current;
                return temp;
            }
            else {
                Node* smallestNode = findSmallestNode(current->right);
                current->data = smallestNode->data;
                current->right = deleteRecursive(current->right, smallestNode->data);
            }
        }
        else if (value < current->data) {
            current->left = deleteRecursive(current->left, value);
        }
        else if (value > current->data) {
            current->right = deleteRecursive(current->right, value);
        }

        return current;
    }

    Node* findSmallestNode(Node* current) {
        while (current->left != nullptr) {
            current = current->left;
        }
        return current;
    }

    Node* searchRecursive(Node* current, int value) {
        if (current == nullptr || current->data == value) {
            return current;
        }

        if (value < current->data) {
            return searchRecursive(current->left, value);
        }
        else {
            return searchRecursive(current->right, value);
        }
    }

    int findHeightRecursive(Node* current) {
        if (current == nullptr) {
            return -1;
        }

        int leftHeight = findHeightRecursive(current->left);
        int rightHeight = findHeightRecursive(current->right);

        return max(leftHeight, rightHeight) + 1;
    }

    void inorderTraversalRecursive(Node* current) {
        if (current != nullptr) {
            inorderTraversalRecursive(current->left);
            cout << current->data << " ";
            inorderTraversalRecursive(current->right);
        }
    }

